package com.cpq.currency.resource;
import com.cpq.common.dto.ApiResponse; import com.cpq.common.security.RoleAllowed; import com.cpq.common.security.SessionHelper; import com.cpq.currency.dto.*; import com.cpq.currency.entity.*; import com.cpq.currency.service.ExchangeRateService; import com.cpq.customer.entity.Customer; import io.vertx.core.http.HttpServerRequest; import jakarta.inject.Inject; import jakarta.ws.rs.*; import jakarta.ws.rs.core.*; import java.util.*;
@Path("/api/cpq/customers/{customerNo}/exchange-rate-strategy") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) @RoleAllowed({"SALES_MANAGER","PRICING_MANAGER","SYSTEM_ADMIN"})
public class CustomerExchangeRateStrategyResource {
 @Inject ExchangeRateService service; @Inject SessionHelper session; @Context HttpServerRequest request;
 private UUID customer(String no){Customer c=Customer.find("code",no).firstResult();if(c==null)throw new NotFoundException("customer not found");return c.id;}
 @GET public ApiResponse<CustomerExchangeRateStrategy> get(@PathParam("customerNo")String no){return ApiResponse.success(service.strategy(customer(no)));}
 @PUT public ApiResponse<CustomerExchangeRateStrategy> put(@PathParam("customerNo")String no,ExchangeRateStrategyRequest r){return ApiResponse.success(service.saveStrategy(customer(no),r,session.getCurrentUserIdOrFallback(request)));}
 @POST @Path("/simulate") public ApiResponse<Map<String,Object>> simulate(@PathParam("customerNo")String no,Map<String,Object> body){
  UUID id=customer(no); ExchangeRateStrategyRequest r=new ExchangeRateStrategyRequest(); if(body!=null){r.method=(String)body.get("method");r.windowUnit=(String)body.get("windowUnit");if(body.get("windowNum")!=null)r.windowNum=Integer.valueOf(body.get("windowNum").toString());if(body.get("dayOfMonth")!=null)r.dayOfMonth=Integer.valueOf(body.get("dayOfMonth").toString());if(body.get("specificDate")!=null)r.specificDate=java.time.LocalDate.parse(body.get("specificDate").toString());}
  String code=body==null?"CNY":String.valueOf(body.getOrDefault("currency","CNY"));java.time.LocalDate date=body==null||body.get("baseDate")==null?java.time.LocalDate.now():java.time.LocalDate.parse(body.get("baseDate").toString());CustomerExchangeRateStrategy s=new CustomerExchangeRateStrategy();s.customerId=id;s.method=r.method;s.windowNum=r.windowNum;s.windowUnit=r.windowUnit;s.dayOfMonth=r.dayOfMonth;s.specificDate=r.specificDate;java.math.BigDecimal rate=service.resolve(code,date,s);return ApiResponse.success(Map.of("currency",code,"baseDate",date,"effectiveDate",service.effectiveDate(code,date,s),"rate",rate.toPlainString())); }
}
